  // 定制权限-主表格-扩展主表格接口方法
  tenant_custom_per_table_main_datasource_extend_view: {
    type: 'custom',
    selector: {
      attr: 'id',
      value: 'tenant_custom_per_table_main' // 主表格页面节点id
    },
    // beforeOperate: 扩展执行前的钩子函数 （见 扩展说明-扩展类型）
    beforeOperate: (app, operateItem, options) => {
      // 数据源-获取主表格
      let tableDataDsConfig = options.element.ds_config.list.find(
        (item) => item.name === 'tableData'
      )
      tableDataDsConfig.reqPrep = operateItem.view.ds_config.list[0].reqPrep
      tableDataDsConfig.reqAfter = operateItem.view.ds_config.list[0].reqAfter

      // 数据源-删除主表格某行
      let delTableDataDsConfig = options.element.ds_config.list.find(
        (item) => item.name === 'delTableData'
      )
      delTableDataDsConfig.reqPrep = operateItem.view.ds_config.list[1].reqPrep
    },
    view: {
      // ds_config：数据源 （见 框架-数据源）
      ds_config: {
        list: [
          {
            name: 'tableData',
            // 请求执行前-可获取当前请求的所有参数
            reqPrep: (vm, options, config) => {
              // 搜索全部时需要展全部
              if (options.params.args.filter.length === 0) {
                vm.$ds.needClearExpand = true
              } else {
                vm.$ds.needClearExpand = false
                // 有搜索条件时，把搜索条件换成精确搜索
                const generateCode = (arr) => {
                  return arr.map((item) => {
                    if (Array.isArray(item)) {
                      const [key, operator, value] = item
                      const newValue = value.replace(/%/g, '')
                      return [key, '=', newValue]
                    } else {
                      return item
                    }
                  })
                }
                options.params.args.filter = generateCode(
                  options.params.args.filter
                )
              }
              // 修改请求参数
              options.params.app = 'sie-iidp-iam'
              options.params.model = 'custom_permission'
              options.params.service = 'searchNodesWildcardOfCustomPer'
              // 获取tab激活
              const activeTab =
                tech_app.page.getNode('functional_permission_tab')?.data
                  ?.activeId ?? '"functional_tab"'
              let tabValue = activeTab === 'functional_tab'
              options.params.args.type = tabValue
                ? 'function'
                : 'custom_function'
              return options
            },
            // 调用接口后执行，可修改数据格式，必须返回res
            reqAfter: (vm, res, config) => {
              // 展开、收起树
              const table = tech_app.page.getNode(
                'tenant_custom_per_table_main_table'
              )
              if (vm.$ds.needClearExpand) {
                table.instance.getInstance().clearTreeExpand()
              } else {
                setTimeout(() => {
                  table.instance.getInstance().setAllTreeExpand(true)
                })
              }
              return res
            }
          },
          {
            name: 'delTableData',
            // 请求执行前
            reqPrep: (vm, options, config) => {
              // 修改请求参数
              options.params.app = 'sie-iidp-iam'
              options.params.model = 'custom_permission'

              const activeTab =
                tech_app.page.getNode('functional_permission_tab')?.data
                  ?.activeId ?? '"functional_tab"'
              let tabValue = activeTab === 'functional_tab'
              // 获取tab激活
              options.params.args.type = tabValue
                ? 'function'
                : 'custom_function'
              return options
            }
          }
        ]
      }
    }
  },

